{
  "aggregate": "master_question",
  "pipeline": {{
    (() => {
      const targetDomains = this.params.domains || [];
      const targetOrigins = this.params.origins || [];
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";

      let matchConditions = {};

      // 1. Domain-Filter
      if (Array.isArray(targetDomains)) {
        if (targetDomains.length > 0) {
          matchConditions["domain"] = { "$in": targetDomains };
        } else {
          matchConditions["domain"] = { "$in": [] }; // Nichts matchen, wenn leer
        }
      } else if (typeof targetDomains === "string" && targetDomains.trim() !== "") {
        matchConditions["domain"] = targetDomains;
      }

      // 2. Origin-Filter (Neu: Prüft, ob 'origin' in den übergebenen Quellen enthalten ist)
      if (Array.isArray(targetOrigins) && targetOrigins.length > 0) {
        matchConditions["origin"] = { "$in": targetOrigins };
      }

      // 3. Zusätzlicher Filter für countWrong > 0, falls true
      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }

      let pipeline = [];

      // `$match` mit allen Bedingungen
      pipeline.push({
        "$match": matchConditions
      });

      // Danach nach Domain gruppieren und zählen
      pipeline.push(
        {
          "$group": {
            "_id": "$domain",
            "total": { "$sum": 1 }
          }
        },
        {
          "$sort": { "_id": 1 }
        }
      );

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": 100
  }
}
